/** Recent command events across all audit files, oldest first. */
export function readCommandHistory(auditDir: string, limit = 30): CommandAuditRow[] {
	if (!fs.existsSync(auditDir)) return [];
	const rows: CommandAuditRow[] = [];
	const files = fs
		.readdirSync(auditDir)
		.filter((name) => name.endsWith(".jsonl"))
		.sort();
	for (const name of files.slice(-7)) {
		for (const line of readUtf8(path.join(auditDir, name)).split(/\r?\n/).filter(Boolean)) {
			try {
				const row = JSON.parse(line);
				if (row.kind !== "command") continue;
				const d = row.details || {};
				rows.push({ ts: row.ts, phase: String(d.phase || row.action), command: String(d.command || ""), cwd: d.cwd, exitCode: d.exitCode });
			} catch {
				// skip malformed lines
			}
		}
	}
	return rows.slice(-limit);
}

export function registerCommandAudit(host: CoreHost): void {
	activeHost = host;
	const { context, output } = host;
	context.subscriptions.push(
		{ dispose: () => (activeHost = undefined) },
		vscode.commands.registerCommand("vibe-code.showCommandHistory", async () => {
			const paths = ensureWorkspacePaths(true);
			if (!paths) return;
			const rows = readCommandHistory(paths.audit);
			output.show(true);
			output.appendLine("\n=== 명령 실행 이력 (최근 7일, 최대 30건) ===");
			if (rows.length === 0) output.appendLine("  (기록된 명령 실행 없음)");
			for (const row of rows) {
				const mark = row.phase === "denied" ? "✗ 거부" : row.phase === "approved" ? "▶ 승인" : row.exitCode === 0 ? "✓ 종료 0" : `! 종료 ${row.exitCode}`;
				output.appendLine(`  ${row.ts} :: ${mark} :: ${row.command}${row.cwd ? ` (cwd: ${row.cwd})` : ""}`);
			}
			output.appendLine("=========================================\n");
		}),
	);
	log(host, "command audit hook registered");
}

/** Body of a `### <name>` sub-section up to the next `### ` or `## ` heading, trimmed. */
export function subsection(text: string, name: string): string {
	const re = new RegExp("(?:^|\\n)### " + escapeRegExp(name) + "\\n([\\s\\S]*?)(?=\\n### |\\n## |$)");
	return (normalizeEol(text).match(re)?.[1] || "").trim();
}

/**
 * Replace the body of a `## <name>` section with `lines`; unchanged when the section is missing.
 * 입력의 줄바꿈을 그대로 돌려준다.
 */
export function writeSection(text: string, name: string, lines: string[]): string {
	const eol = detectEol(text);
	const body = normalizeEol(text);
	const re = new RegExp(sectionHeadRe(name).source + "([\\s\\S]*?)(?=\\n## |$)");
	if (!re.test(body)) return text;
	return restoreEol(
		body.replace(re, (_match, head: string) => head + (lines.length > 0 ? lines.join("\n") + "\n" : "\n")),
		eol,
	);
}

/**
 * Lines of a `## <name>` section exactly as written — indentation and non-checklist notes kept.
 * An empty or missing section is `[]`, never `[""]`. Pair with `writeSection` to edit a section
 * without dropping the lines the editor does not care about.
 */
export function sectionLines(text: string, name: string): string[] {
	const body = section(text, name);
	return body === "" ? [] : body.split("\n");
}

